import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"第四十四卦 姤 天風姤 乾上巽下","description":"周易 - 第四十四卦 姤 天風姤 乾上巽下","frontmatter":{"title":"第四十四卦 姤 天風姤 乾上巽下","description":"周易 - 第四十四卦 姤 天風姤 乾上巽下"},"headers":[],"relativePath":"classics/zhouyi/045.md","filePath":"classics/zhouyi/045.md"}'),l={name:"classics/zhouyi/045.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="姤" tabindex="-1">姤 <a class="header-anchor" href="#姤" aria-label="Permalink to “姤”">​</a></h1><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>女壯，勿用取女。</p><h3 id="彖傳" tabindex="-1">彖傳 <a class="header-anchor" href="#彖傳" aria-label="Permalink to “彖傳”">​</a></h3><p>姤，遇也，柔遇剛也。勿用取女，不可與長也。天地相遇，品物鹹章也。剛遇中正，天下大行也。姤之時義大矣哉！</p><h3 id="象傳" tabindex="-1">象傳 <a class="header-anchor" href="#象傳" aria-label="Permalink to “象傳”">​</a></h3><p>天下有風，姤；後以施命誥四方。</p><h3 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h3><p>繫於金柅，貞吉，有攸往，見兇， 羸豕踟躅。象曰：繫於金柅，柔道牽也。</p><h3 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h3><p>包有魚，無咎，不利賓。象曰：包有魚，義不及賓也。</p><h3 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h3><p>臀無膚，其行次且，厲，無大咎。象曰：其行次且，行未牽也。</p><h3 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h3><p>包無魚，起兇。象曰：無魚之兇，遠民也。</p><h3 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h3><p>以杞包瓜，含章，有隕自天。象曰：九五含章，中正也。有隕自天，志不捨命也。</p><h3 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h3><p>姤其角，吝，無咎。象曰：姤其角，上窮吝也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
